# kmsqrt leg at 9fde8f5f703ef88e1258ebe1909c230a2ab4f4e3 (kmsqrt agent, 2026-09-14 night). RunPod passes no environment: commit, base and lanes baked here.
# Arm U (unfixed): the four k-means source files of the base commit e2d770ba8b616034b564e82e864d09b23f8e132b swapped in, the core binding built,
# the inertia bits printed and kmeans-sqrt run. Arm F (fixed): the files restored, rebuilt, bits printed, and
# every kmeans lane run.
set -u
R=9fde8f5f703ef88e1258ebe1909c230a2ab4f4e3
B=e2d770ba8b616034b564e82e864d09b23f8e132b
LANES=kmeans,kmeans-random,kmeans-array,kmeans-weighted,kmeans-sqrt,kmeans-classic-pp,kmeans-cosine,par-kmeans
cd /root/mojolearn || exit 9
OUT=/root/gemm_leg_out/kmsqrt
mkdir -p "$OUT/logs"
G="$OUT/gate.txt"
say() { echo "$@" >> "$G"; }
say "started=$(date -u +%Y-%m-%dT%H:%M:%SZ) commit=$R base=$B"
(nvidia-smi --query-gpu=name,compute_cap --format=csv,noheader 2>/dev/null; rocminfo 2>/dev/null | grep -E 'Marketing Name|^ *Name: +gfx') > "$OUT/logs/device.txt" 2>&1
say "device=$(tr '\n' ' ' < "$OUT/logs/device.txt")"
LABEL=nvidia-h100-sm_90a
if [ -z "${MOJOLEARN_GPU_ARCHS:-}" ]; then
    if command -v nvidia-smi >/dev/null 2>&1 && nvidia-smi -L >/dev/null 2>&1; then
        _cc=$(nvidia-smi --query-gpu=compute_cap --format=csv,noheader | head -1 | tr -d ' ')
        case "$_cc" in 9.0) MOJOLEARN_GPU_ARCHS=sm_90a ;; 8.9) MOJOLEARN_GPU_ARCHS=sm_89 ;; 8.6) MOJOLEARN_GPU_ARCHS=sm_86 ;; 8.0) MOJOLEARN_GPU_ARCHS=sm_80 ;; 12.0) MOJOLEARN_GPU_ARCHS=sm_120a ;; *) MOJOLEARN_GPU_ARCHS="sm_$(echo "$_cc" | tr -d .)" ;; esac
    elif command -v rocminfo >/dev/null 2>&1; then
        MOJOLEARN_GPU_ARCHS=$(rocminfo 2>/dev/null | grep -m1 -oE 'gfx[0-9a-z]+')
    fi
    export MOJOLEARN_GPU_ARCHS
fi
case "$LABEL" in *"-${MOJOLEARN_GPU_ARCHS:-none}") ;; *) say "LABEL $LABEL does not end in the resolved arch ${MOJOLEARN_GPU_ARCHS:-unset}; refusing"; exit 7 ;; esac
say "gpu_archs_resolved=${MOJOLEARN_GPU_ARCHS:-unset} label=$LABEL"
cat > "$OUT/probe.py" <<'PY'
import sys, numpy as np
sys.path.insert(0, "/root/mojolearn/tools")
import identity_break as ib
import mojolearn as ml
for kind in sys.argv[1].split(","):
    X, yc, yr = ib.fixture(kind)
    for metric in ("l2_sqrt_expanded", "l2_expanded"):
        m = ml.KMeans(n_clusters=8, random_state=3, metric=metric).fit(X)
        C = np.asarray(m.cluster_centers_, dtype=np.float64)
        Xd = X.astype(np.float64)
        d2 = ((Xd[:, None, :] - C[None, :, :]) ** 2).sum(-1)
        lab = np.asarray(m.labels_).astype(np.int64)
        bad = int(np.sum(d2[np.arange(len(X)), lab] > d2.min(1) + 1e-4 * np.maximum(d2.min(1), 1.0)))
        print(f"PROBE {kind} {metric}: inertia_bits={np.float64(m.inertia_).tobytes().hex()} inertia={m.inertia_!r} "
              f"inertia_h={ib._h(np.float64(m.inertia_))} centers_h={ib._h(m.cluster_centers_)} labels_h={ib._h(m.labels_)} "
              f"labels_not_argmin={bad}", flush=True)
PY
build_core() {
    _t0=$(date +%s)
    env MOJOLEARN_NUMERIC_MODE=identical MOJOLEARN_SKIP_BUILD_GATE=1 MOJOLEARN_COMPILE_JOBS=8 sh bindings/build.sh > "$OUT/logs/build_$1.log" 2>&1
    _e=$?
    say "build_$1 exit=$_e seconds=$(( $(date +%s) - _t0 )) so_sha=$(sha256sum python/mojolearn/identical/_mojolearn.so 2>/dev/null | cut -c1-16)"
    return $_e
}
PY_RUN="env MOJOLEARN_NUMERIC_MODE=identical PYTHONPATH=/root/mojolearn/python pixi run python"
# ---- arm U: unfixed
mkdir -p /root/fixed_src && tar cf /root/fixed_src/fixed.tar cluster/estimator.mojo cluster/host/kmeans_oracle.mojo cluster/impl/distance/fused_distance_nn/simt_kernel.mojo cluster/impl/distance/unfused_distance_nn.mojo
base64 -d > /root/unfixed.tgz <<'B64'

B64
tar xzf /root/unfixed.tgz -C /root/mojolearn && say "unfixed files swapped in: $(grep -c 'best_v = sqrt(best_v)' cluster/impl/distance/fused_distance_nn/simt_kernel.mojo) stdlib-sqrt lines in the fused kernel"
echo "$B" > /root/mojolearn/commit.txt
if build_core unfixed; then
    $PY_RUN "$OUT/probe.py" wide,base > "$OUT/logs/probe_unfixed.log" 2>&1; say "probe_unfixed exit=$?"
    grep PROBE "$OUT/logs/probe_unfixed.log" | sed 's/^/U /' >> "$G"
    $PY_RUN tools/identity_break.py --lanes kmeans-sqrt --vendor "$LABEL" --json "$OUT/identity_break.$LABEL.unfixed.json" > "$OUT/logs/identity_break_unfixed.log" 2>&1
    say "identity_unfixed exit=$?"
fi
# ---- arm F: fixed
tar xf /root/fixed_src/fixed.tar -C /root/mojolearn && say "fixed files restored: $(grep -c 'best_v = identical_sqrt(best_v)' cluster/impl/distance/fused_distance_nn/simt_kernel.mojo) identical_sqrt lines in the fused kernel"
echo "$R" > /root/mojolearn/commit.txt
if build_core fixed; then
    $PY_RUN "$OUT/probe.py" wide,base > "$OUT/logs/probe_fixed.log" 2>&1; say "probe_fixed exit=$?"
    grep PROBE "$OUT/logs/probe_fixed.log" | sed 's/^/F /' >> "$G"
    t0=$(date +%s)
    $PY_RUN tools/identity_break.py --lanes "$LANES" --vendor "$LABEL" --json "$OUT/identity_break.$LABEL.json" > "$OUT/logs/identity_break_fixed.log" 2>&1
    say "identity_fixed exit=$? seconds=$(( $(date +%s) - t0 ))"
fi
for f in "$OUT"/logs/identity_break*.log; do
    echo "--- $f" >> "$G"
    grep -E "^cells=|^infer:|^model:|^batch:|MOVED|REFUSED|^wrote|Traceback|Error" "$f" 2>/dev/null | cut -c1-300 | head -20 >> "$G"
done
say "finished=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
exit 0
